package com.opensocket.aievent.core.integration.issue;
import java.time.OffsetDateTime; import java.util.*; import java.util.concurrent.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Repository; import com.opensocket.aievent.core.integration.issue.projection.*; import com.opensocket.aievent.core.issuetracking.contract.ProjectionLifecycleStatus;
@Repository @ConditionalOnProperty(prefix="issue-projection",name="store",havingValue="MEMORY",matchIfMissing=true)
public class InMemoryIssueProjectionStateRepository implements IssueProjectionStateRepository {
 private final Map<String,IssueProjectionState> states=new ConcurrentHashMap<>(); private final Map<String,IssueProjectionReconciliationCase> cases=new ConcurrentHashMap<>(); private final Set<String> events=ConcurrentHashMap.newKeySet(); private String key(String t,String id){return t+"|"+id;}
 public IssueProjectionState save(IssueProjectionState v){states.put(key(v.tenantId(),v.projectionId()),v);return v;} public Optional<IssueProjectionState> find(String t,String id){return Optional.ofNullable(states.get(key(t,id)));} public Optional<IssueProjectionState> findByAggregateKey(String t,String k){return states.values().stream().filter(v->t.equals(v.tenantId())&&k.equals(v.projectionAggregateKey())&&v.lifecycleStatus()!=ProjectionLifecycleStatus.SUPERSEDED&&v.lifecycleStatus()!=ProjectionLifecycleStatus.DISABLED).findFirst();} public Optional<IssueProjectionState> findBySourceEvent(String t,String id){return states.values().stream().filter(v->t.equals(v.tenantId())&&id.equals(v.sourceEventId())).findFirst();} public Optional<IssueProjectionState> findByTaskIssueLink(String t,String id){return states.values().stream().filter(v->t.equals(v.tenantId())&&id.equals(v.taskIssueLinkId())).max(Comparator.comparing(IssueProjectionState::updatedAt));} public Optional<IssueProjectionState> findLatestByTask(String t,String id){return states.values().stream().filter(v->t.equals(v.tenantId())&&id.equals(v.taskId())&&v.lifecycleStatus()!=ProjectionLifecycleStatus.SUPERSEDED).max(Comparator.comparing(IssueProjectionState::updatedAt));} public List<IssueProjectionState> list(String t,ProjectionLifecycleStatus state,int limit){return states.values().stream().filter(v->t.equals(v.tenantId())&&(state==null||state==v.lifecycleStatus())).sorted(Comparator.comparing(IssueProjectionState::updatedAt).reversed()).limit(limit).toList();} public List<IssueProjectionState> listDue(OffsetDateTime now,int limit){return states.values().stream().filter(v->v.lifecycleStatus()==ProjectionLifecycleStatus.FAILED&&v.nextRetryAt()!=null&&!v.nextRetryAt().isAfter(now)).sorted(Comparator.comparing(IssueProjectionState::nextRetryAt)).limit(limit).toList();} public boolean tryRecordDomainEvent(String t,String p,String e,long s,String h,OffsetDateTime a){return events.add(key(t,e));}
 public IssueProjectionReconciliationCase saveCase(IssueProjectionReconciliationCase v){cases.put(key(v.tenantId(),v.caseId()),v);return v;} public Optional<IssueProjectionReconciliationCase> findCase(String t,String id){return Optional.ofNullable(cases.get(key(t,id)));} public Optional<IssueProjectionReconciliationCase> findOpenCaseByProjection(String t,String p){return cases.values().stream().filter(v->t.equals(v.tenantId())&&p.equals(v.projectionId())&&Set.of(IssueProjectionReconciliationStatus.OPEN,IssueProjectionReconciliationStatus.RETRY_SCHEDULED,IssueProjectionReconciliationStatus.WAIT_HUMAN).contains(v.status())).findFirst();} public List<IssueProjectionReconciliationCase> listCases(String t,IssueProjectionReconciliationStatus s,int l){return cases.values().stream().filter(v->t.equals(v.tenantId())&&(s==null||s==v.status())).sorted(Comparator.comparing(IssueProjectionReconciliationCase::createdAt).reversed()).limit(l).toList();} public String mode(){return "MEMORY";}
}
